from __future__ import absolute_import
import re

from hran_file_operations.parsers.scfc.base import UniversalScfcParser


class SwbtScfcParser(UniversalScfcParser):
    """
    SWBT-specific implementation of SCFC Parser.
    """
    rm_dir = {'FRGF': ['192.168.255.69', '192.168.255.73'],
              'FRDB': ['192.168.254.129', '192.168.254.133'],
              'FRGT': ['192.168.254.129', '192.168.254.133'],
              'FRDA': ['192.168.254.129', '192.168.254.133'],
              'FRGP': ['192.168.254.129', '192.168.254.133']}

    def __init__(self, scfc, from_string=False, logger=None):

        super(SwbtScfcParser, self).__init__(scfc, from_string, logger=logger)
        self.managed_obj = self.root.xpath(
            "//ns:managedObject[@class='MRBTS' "
            "and contains(@distName, 'WBTS-')]",
            namespaces=self.ns_dict)[0]

    @property
    def _raw_units(self):
        _raw_units = []
        for items in self.managed_obj.xpath(".//ns:list/ns:item",
                                            namespaces=self.ns_dict):
            _raw_units.append({i.attrib["name"]: i.text for i in
                               items.xpath(".//ns:p",
                                           namespaces=self.ns_dict)})
        if not _raw_units:
            self.logger.error('Unit list is empty!')
        return _raw_units

    @property
    def units(self):
        units = {u["unitName"] + u["unitNumber"]: u["variant"] for u in
                 self._raw_units}
        units["WbtsId"] = re.search('WBTS-(\d+)',
                                    self.managed_obj.attrib["distName"]).group(
            1)
        return units

    @property
    def cells(self):
        cells = {"NR": [], "LTE": [], "GSM": [], "WCDMA": []}
        cells_nodes = self.root.xpath('.//ns:managedObject[@class="LCELW"]',
                                      namespaces=self.ns_dict)
        for c in cells_nodes:
            parameters = {p.attrib["name"]: p.text for p in
                          c.xpath(".//ns:p", namespaces=self.ns_dict)}
            resources = {r.attrib["name"]: r.text for r in
                         c.xpath(".//ns:list/ns:item/ns:p",
                                 namespaces=self.ns_dict)}
            cell_id = re.search('LCELW-(\d+)', c.attrib["distName"]).group(1)
            cells["WCDMA"].append(
                {"cell_id": cell_id, "parameters": parameters,
                 "resources": resources})
        return cells

    @property
    def rmods(self):
        radios = []
        for u in self._raw_units:
            radio = {}
            unit_name = u["unitName"] + u["variant"]
            if unit_name in self.rm_dir:
                radio["unit_name"] = unit_name
                if radios:
                    radio["ip"] = self.rm_dir[unit_name][1]
                else:
                    radio["ip"] = self.rm_dir[unit_name][0]
                radios.append(radio)
        return radios

    @property
    def smods(self):
        self.logger.error('Property "smods" is not implemented for {}'.format(
            self.__class__.__name__))
        return []
